code='''def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if not col or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); cells=[]
        while stack:
          y,x=stack.pop(); cells.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(y+dy,x+dx)
            if 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]==col:
              seen.add(q); stack.append(q)
        comps.append((col,cells))
    def canon(cells):
      pts=[(y,x) for y,x in cells]; forms=[]
      for k in range(8):
        arr=[]
        for y,x in pts:
          if k<4: a,b=((y,x),(x,-y),(-y,-x),(-x,y))[k]
          else: a,b=((y,-x),(x,y),(-y,x),(-x,-y))[k-4]
          arr.append((a,b))
        my=min(a for a,b in arr); mx=min(b for a,b in arr)
        forms.append(tuple(sorted((a-my,b-mx) for a,b in arr)))
      return min(forms)
    groups={}
    for col,cells in comps: groups.setdefault(canon(cells),[]).append(col)
    out=[row[:] for row in grid]
    for col,cells in comps:
      colors=groups[canon(cells)]
      if len(colors)>1:
        # recolor to other colored matching object
        target=next((x for x in colors if x!=col),col)
        for y,x in cells: out[y][x]=target
    return out
'''
